# Generated by agents-cli 1.11.0; needs google-adk and model access.
import unittest

try:
    import google.adk  # noqa: F401
    HAVE_ADK = True
except ImportError:
    HAVE_ADK = False


@unittest.skipUnless(HAVE_ADK, "google-adk is not installed")
class AgentStreamTest(unittest.IsolatedAsyncioTestCase):
    async def test_agent_replies(self):
        from google.adk.runners import InMemoryRunner
        from google.genai import types

        from app.agent import app

        runner = InMemoryRunner(app=app)
        session = await runner.session_service.create_session(app_name="app", user_id="s-100")
        events = [e async for e in runner.run_async(
            user_id="s-100", session_id=session.id,
            new_message=types.Content(role="user", parts=[types.Part(text="How do I connect to the VPN?")]))]
        self.assertTrue(any(e.is_final_response() for e in events))
